#include <iostream>
#include <string>
#include <functional>
using namespace std;

class ScopeGuard {
    function<void()> cleanup;
public:
    ScopeGuard(function<void()> fn) : cleanup(fn) {}
    ~ScopeGuard() { if (cleanup) cleanup(); }
};

class Context {
    string name;
public:
    Context(const string& n) : name(n) { cout << "Enter " << name << endl; }
    ~Context() { cout << "Exit " << name << endl; }
};

int main() {
    {
        Context ctx("main");
        ScopeGuard guard([]() { cout << "Cleanup resources" << endl; });
        cout << "Working..." << endl;
    }
    return 0;
}
